type ProfilePaymentFields = {
  stripe_account_id?: unknown;
  stripe_onboarding_complete?: unknown;
} | null | undefined;

export const hasConnectedStripeAccount = (profile: ProfilePaymentFields) => {
  const accountId = typeof profile?.stripe_account_id === 'string'
    ? profile.stripe_account_id.trim()
    : '';

  return Boolean(accountId && accountId.toLowerCase() !== 'sandbox');
};

export const shouldShowProfilePaymentSetupWarning = (profile: ProfilePaymentFields) =>
  profile?.stripe_onboarding_complete === false && !hasConnectedStripeAccount(profile);
