import React from 'react';
import { motion } from 'motion/react';
import { Play, Clock, Star, Users, BookOpen, ArrowUpRight } from 'lucide-react';
import { Link } from 'react-router-dom';

interface CourseCardProps {
  id: string;
  title: string;
  instructor: string;
  price: number;
  rating: number;
  students: number;
  duration: string;
  image: string;
  category: string;
  currency?: string;
}

export const CourseCard = ({ id, title, instructor, price, rating, students, duration, image, category, currency = 'EUR' }: CourseCardProps) => {
  return (
    <Link to={`/listing/${id}`} className="block group h-full">
      <motion.div 
        whileHover={{ y: -10 }}
        transition={{ duration: 0.4, ease: [0.23, 1, 0.32, 1] }}
        className="bg-white dark:bg-[#141414] rounded-[2.5rem] overflow-hidden border border-black/5 dark:border-white/5 shadow-xl hover:shadow-2xl hover:border-indigo-500/30 transition-all duration-500 h-full flex flex-col"
      >
        <div className="relative aspect-video overflow-hidden">
          {image ? (
            <img src={image} alt={title} loading="lazy" decoding="async" className="w-full h-full object-cover transition-transform duration-700 ease-out" />
          ) : (
            <div className="h-full w-full bg-gradient-to-br from-indigo-500/20 to-blue-500/5" aria-hidden="true" />
          )}
          <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-60 group-hover:opacity-80 transition-opacity duration-500" />
          
          <div className="absolute top-4 left-4 px-4 py-1.5 bg-white/10 backdrop-blur-xl border border-white/10 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white shadow-2xl">
            {category}
          </div>

          <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-500">
            <div className="w-16 h-16 bg-white/20 backdrop-blur-xl rounded-full flex items-center justify-center text-white border border-white/30 shadow-2xl transform scale-90 group-hover:scale-100 transition-transform duration-500">
              <Play className="w-6 h-6 ml-1 fill-current" />
            </div>
          </div>
        </div>
        
        <div className="p-8 flex-1 flex flex-col relative">
          <div className="absolute top-0 right-0 p-8 opacity-[0.02] pointer-events-none">
            <BookOpen className="w-20 h-20" />
          </div>

          {(duration || students > 0) && (
            <div className="flex items-center gap-3 text-[10px] font-black uppercase tracking-widest text-gray-500 mb-4">
              {duration && <span className="flex items-center gap-1.5"><Clock className="w-3.5 h-3.5 text-indigo-500" /> {duration}</span>}
              {duration && students > 0 && <span className="opacity-30">•</span>}
              {students > 0 && <span className="flex items-center gap-1.5"><Users className="w-3.5 h-3.5 text-indigo-500" /> {students.toLocaleString()} students</span>}
            </div>
          )}
          
          <h3 className="text-2xl font-black italic uppercase tracking-tighter text-gray-900 dark:text-white mb-2 leading-[0.9] line-clamp-2 group-hover:text-indigo-500 transition-colors">
            {title}
          </h3>
          
          <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-8">by {instructor}</p>
          
          <div className="mt-auto flex items-end justify-between pt-6 border-t border-gray-100 dark:border-white/5">
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1">Rating</span>
              <div className="flex items-center gap-2">
                {rating > 0 ? (
                  <>
                    <Star className="w-4 h-4 text-yellow-500 fill-current" />
                    <span className="font-black text-lg text-gray-900 dark:text-white leading-none">{rating.toFixed(1)}</span>
                  </>
                ) : (
                  <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">No reviews</span>
                )}
              </div>
            </div>
            
            <div className="flex flex-col items-end">
              <span className="text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1">Price</span>
              <div className="text-3xl font-black italic tracking-tighter text-gray-900 dark:text-white leading-none">
                {new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(price)}
              </div>
            </div>
          </div>
        </div>
      </motion.div>
    </Link>
  );
};
